-- Asignacion de estudiantes a las paradas de la ruta SENA Vuelta
-- Usando RouteStop.Id (F7000211...) no Stop.Id
INSERT INTO Route.RouteStudentAssignments (Id, ProfileId, RouteStopId, Status)
SELECT v.Id, v.ProfileId, v.RouteStopId, 'Active'
FROM (VALUES
    -- Parada 1: F7000211
    ('F5000031-0000-4000-8000-000000000031', 'C1000039-0000-4000-8000-000000000039', 'F7000211-0000-4000-8000-000000000211'),
    ('F5000032-0000-4000-8000-000000000032', 'C1000040-0000-4000-8000-000000000040', 'F7000211-0000-4000-8000-000000000211'),
    -- Parada 2: F7000212
    ('F5000033-0000-4000-8000-000000000033', 'C1000041-0000-4000-8000-000000000041', 'F7000212-0000-4000-8000-000000000212'),
    ('F5000034-0000-4000-8000-000000000034', 'C1000042-0000-4000-8000-000000000042', 'F7000212-0000-4000-8000-000000000212'),
    -- Parada 3: F7000213
    ('F5000035-0000-4000-8000-000000000035', 'C1000043-0000-4000-8000-000000000043', 'F7000213-0000-4000-8000-000000000213'),
    ('F5000036-0000-4000-8000-000000000036', 'C1000044-0000-4000-8000-000000000044', 'F7000213-0000-4000-8000-000000000213'),
    -- Parada 4: F7000214
    ('F5000037-0000-4000-8000-000000000037', 'C1000045-0000-4000-8000-000000000045', 'F7000214-0000-4000-8000-000000000214'),
    ('F5000038-0000-4000-8000-000000000038', 'C1000046-0000-4000-8000-000000000046', 'F7000214-0000-4000-8000-000000000214'),
    -- Parada 5: F7000215
    ('F5000039-0000-4000-8000-000000000039', 'C1000047-0000-4000-8000-000000000047', 'F7000215-0000-4000-8000-000000000215'),
    ('F5000040-0000-4000-8000-000000000040', 'C1000048-0000-4000-8000-000000000048', 'F7000215-0000-4000-8000-000000000215'),
    -- Parada 6: F7000216
    ('F5000041-0000-4000-8000-000000000041', 'C1000049-0000-4000-8000-000000000049', 'F7000216-0000-4000-8000-000000000216'),
    ('F5000042-0000-4000-8000-000000000042', 'C1000050-0000-4000-8000-000000000050', 'F7000216-0000-4000-8000-000000000216')
) AS v (Id, ProfileId, RouteStopId)
WHERE NOT EXISTS (SELECT 1 FROM Route.RouteStudentAssignments rsa WHERE rsa.ProfileId = v.ProfileId AND rsa.RouteStopId = v.RouteStopId);